import{s as i}from"./supabase-D0OOETQO.js";if(localStorage.getItem("logged_in")!=="true"||localStorage.getItem("user_role")!=="collector")window.location.href="login.html";else{const e=localStorage.getItem("user_name")||"Collector";document.getElementById("welcomeCollector").innerText=`Halo, ${e}!`}window.logout=function(){localStorage.clear(),window.location.href="login.html"};var n;(n=document.getElementById("formLogAktivitas"))==null||n.addEventListener("submit",async e=>{e.preventDefault();const a=e.target.querySelector("button");a.innerText="Menyimpan...";const o=document.getElementById("select_debitur").value,l=document.getElementById("hasil_tindak_lanjut").value,r=document.getElementById("catatan").value;try{const{error:t}=await i.from("interactions").insert([{debt_id:o,collector_id:localStorage.getItem("user_id"),type:l,notes:r,interaction_date:new Date().toISOString()}]);if(t)throw t;alert("✅ Laporan kunjungan/telepon berhasil disimpan!"),e.target.reset()}catch(t){console.log(t),alert("Simulasi berhasil (Atau gagal simpan jika ID debitur belum valid/belum diikat di database).")}finally{a.innerText="Simpan Laporan"}});
